import pandas as pd

def clean(df):
    d = df.copy()
    if 'island' in d.columns:
        d['island'] = d['island'].astype('string').str.strip().str.title()
    if 'species' in d.columns:
        d['species'] = d['species'].astype('string').str.strip().str.title()
    if 'sex' in d.columns:
        d['sex'] = d['sex'].astype('string').str.strip().str.lower()
    if 'body_mass_g' in d.columns:
        d['body_mass_g'] = pd.to_numeric(
            d['body_mass_g'].astype('string').str.replace(',', '', regex=False),
            errors='coerce'
        )
    if 'flipper_length_mm' in d.columns:
        d['flipper_length_mm'] = pd.to_numeric(
            d['flipper_length_mm'], errors='coerce'
        ).abs()
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    means = d.groupby('species', sort=False)['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in means.items()}
